/* External CSS for EduNext Clone */

body { margin: 0; font-family: 'Inter', Arial, sans-serif; background: #f9fafb; color: #222; }
a { text-decoration: none; color: inherit; }
.container { max-width: 1120px; margin: 0 auto; padding: 0 16px; }

/* Navbar */
.navbar { background: #fff; box-shadow: 0 1px 4px rgba(0,0,0,0.04); border-bottom: 1px solid #e5e7eb; position: sticky; top: 0; z-index: 50; }
.navbar-content { display: flex; justify-content: space-between; align-items: center; height: 64px; }
.navbar-brand { display: flex; align-items: center; gap: 8px; font-size: 1.25rem; font-weight: bold; color: #1e3a8a; }
.navbar-brand-icon { width: 32px; height: 32px; background: #1e3a8a; border-radius: 8px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 1.1rem; }
.navbar-links { display: flex; gap: 24px; }
.navbar-links a { color: #374151; font-weight: 500; transition: color 0.2s; }
.navbar-links a:hover { color: #1e3a8a; }
.navbar-actions { display: flex; gap: 12px; }
.btn { padding: 0.5rem 1.5rem; border-radius: 0.5rem; font-weight: 600; border: none; cursor: pointer; font-size: 1rem; transition: background 0.2s, color 0.2s; }
.btn-primary { background: #1e3a8a; color: #fff; }
.btn-primary:hover { background: #2563eb; }
.btn-outline { background: transparent; border: 2px solid #1e3a8a; color: #1e3a8a; }
.btn-outline:hover { background: #1e3a8a; color: #fff; }

/* Hero */
.hero-section { background: linear-gradient(135deg, #1e3a8a 0%, #1e40af 100%); color: #fff; padding: 80px 0; }
.hero-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }
@media (max-width: 1024px) { .hero-grid { grid-template-columns: 1fr; } }
.hero-title { font-size: 2.5rem; font-weight: bold; margin-bottom: 1.5rem; color: #22c55e; }
.hero-subtitle { font-size: 1.25rem; margin-bottom: 2rem; color: #fde68a; }
.quote-box { background: rgba(255,255,255,0.1); -webkit-backdrop-filter: blur(4px); backdrop-filter: blur(4px); border-radius: 0.75rem; padding: 1.5rem; margin-bottom: 2rem; border: 1px solid rgba(255,255,255,0.2); }
.quote-icon { color: #bfdbfe; font-size: 1.25rem; margin-right: 0.75rem; margin-top: 0.25rem; flex-shrink: 0; }
.quote-text { font-size: 1.125rem; font-style: italic; color: #f9a8d4; margin-bottom: 0.5rem; }
.quote-author { font-size: 0.875rem; color: #fdba74; }
.hero-buttons { display: flex; flex-direction: row; gap: 1rem; }
.hero-image { position: relative; border-radius: 1rem; overflow: hidden; box-shadow: 0 8px 32px rgba(0,0,0,0.25); }
.hero-image img { width: 100%; height: auto; display: block; border-radius: 1rem; }
.hero-image::after { content: ''; position: absolute; inset: 0; background: linear-gradient(to top, rgba(0,0,0,0.2), transparent); border-radius: 1rem; }

/* Features */
.features-section { background: #fff; padding: 80px 0; }
.features-title { text-align: center; font-size: 2rem; font-weight: bold; color: #111827; margin-bottom: 1rem; }
.features-desc { text-align: center; font-size: 1.25rem; color: #6b7280; margin-bottom: 2.5rem; }
.features-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; justify-items: center; }
@media (max-width: 900px) { .features-grid { grid-template-columns: 1fr; } }
.feature-card { text-align: center; }
.feature-icon { width: 64px; height: 64px; border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 1rem; font-size: 2rem; }
.feature-live { background: #1e3a8a; color: #fff; }
.feature-mobile { background: #22c55e; color: #fff; }
.feature-cert { background: #f59e42; color: #fff; }
.feature-left { text-align: left; }
.feature-center { text-align: center; }
.feature-right { text-align: right; }

/* Section, Courses, Live, Teachers, CTA, Footer */
.section { padding: 80px 0; background: #fff; }
.section-title { text-align: center; font-size: 2rem; font-weight: bold; color: #111827; margin-bottom: 1rem; }
.section-desc { text-align: center; font-size: 1.25rem; color: #6b7280; margin-bottom: 2.5rem; }
.footer { background: #1e3a8a; color: #fff; padding: 40px 0; text-align: center; }

/* Custom classes for inline styles moved from HTML */
.flex-between { display: flex; justify-content: space-between; align-items: stretch; gap: 32px; margin-top: 2.5rem; }
.flex-col-left { flex: 1; text-align: left; background: #f1f5f9; border-radius: 1rem; padding: 2.5rem 1.5rem; box-shadow: 0 2px 8px rgba(30,58,138,0.06); display: flex; flex-direction: column; align-items: flex-start; }
.flex-col-center { flex: 1; text-align: center; background: #f1f5f9; border-radius: 1rem; padding: 2.5rem 1.5rem; box-shadow: 0 2px 8px rgba(30,58,138,0.06); display: flex; flex-direction: column; align-items: center; }
.flex-col-right { flex: 1; text-align: right; background: #f1f5f9; border-radius: 1rem; padding: 2.5rem 1.5rem; box-shadow: 0 2px 8px rgba(30,58,138,0.06); display: flex; flex-direction: column; align-items: flex-end; }
